#!/usr/bin/env bun
/** The generated files under deploy/observability/, made from the catalog and the latency budget so
 * they cannot disagree with the code:
 *
 *   dashboards/slo.json, storage.json, runtime.json   Grafana dashboards (tools/dashboards.ts)
 *   alerts/slo.rules.yaml, slo.rules.test.yaml        the latency budget's recording rules and burn
 *                                                     alerts, and their promtool tests (tools/slo.ts)
 *   alerts/ops.rules.test.yaml                        promtool tests of the hand-written alerts
 *                                                     (tools/alert-scenarios.ts)
 *   collector/cloud.yaml                              the allowlist block: the catalog's core metrics
 *
 *   bun packages/telemetry/tools/deploy-files.ts --write     rewrite them
 *   bun packages/telemetry/tools/deploy-files.ts --check     exit 1 if any is stale (a test does this)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { METRICS, METRIC_NAMES, type MetricSpec, exportedName } from "../src/catalog.ts";
import { OPS_SCENARIOS, alertsOf, testYaml } from "./alert-scenarios.ts";
import { DASHBOARDS, renderDashboard } from "./dashboards.ts";
import { sloRulesYaml, sloTestYaml } from "./slo.ts";

export const ROOT = resolve(import.meta.dir, "../../..");
export const DEPLOY = resolve(ROOT, "deploy/observability");

/** The collector's own delivery metrics that are kept besides the catalog's: whether it is getting
 * data out to Grafana Cloud. Anything else it says about itself stays in the pod. */
export const COLLECTOR_SELF =
  "^otelcol_(exporter_(sent|send_failed|enqueue_failed)_.*|exporter_queue_(size|capacity)|processor_.*refused.*|receiver_refused_.*)$";

const START = "# allowlist:start";
const END = "# allowlist:end";

/** The names the cloud collector lets through: the core tier of the catalog. */
export const coreMetricNames = (): string[] =>
  METRIC_NAMES.filter((name) => (METRICS[name] as MetricSpec).tier === "core").map(exportedName);

/** The condition of the filter processor that drops everything else, one name to a line. */
function allowlist(): string[] {
  const indent = "        ";
  const names = coreMetricNames();
  return [
    `${indent}- >-`,
    ...names.map((name, index) => `${indent}  ${index === 0 ? "" : "and "}name != "${name}"`),
    `${indent}  and not IsMatch(name, "${COLLECTOR_SELF}")`,
  ];
}

/** cloud.yaml with its allowlist block replaced. */
export function cloudCollector(current: string): string {
  const from = current.indexOf(START);
  const to = current.indexOf(END);
  if (from < 0 || to < from) throw new Error("cloud.yaml lost its allowlist markers");
  const lineStart = current.lastIndexOf("\n", from) + 1;
  const indent = current.slice(lineStart, from);
  return `${current.slice(0, from)}${START}\n${allowlist().join("\n")}\n${indent}${END}${current.slice(to + END.length)}`;
}

const json = (value: unknown) => `${JSON.stringify(value, null, 2)}\n`;

/** Every generated file: its path under deploy/observability and what it should hold. */
export function generated(): Map<string, string> {
  const out = new Map<string, string>();
  const names = ["slo", "storage", "runtime"];
  DASHBOARDS.forEach((spec, index) => {
    out.set(`dashboards/${names[index]}.json`, json(renderDashboard(spec)));
  });
  out.set("alerts/slo.rules.yaml", sloRulesYaml());
  out.set("alerts/slo.rules.test.yaml", sloTestYaml());
  const ops = readFileSync(resolve(DEPLOY, "alerts/ops.rules.yaml"), "utf8");
  out.set(
    "alerts/ops.rules.test.yaml",
    testYaml(
      "ops.rules.yaml",
      OPS_SCENARIOS,
      alertsOf(Bun.YAML.parse(ops)),
      "# GENERATED by packages/telemetry/tools/deploy-files.ts from tools/alert-scenarios.ts and ops.rules.yaml: do not edit by hand.\n",
    ),
  );
  out.set(
    "collector/cloud.yaml",
    cloudCollector(readFileSync(resolve(DEPLOY, "collector/cloud.yaml"), "utf8")),
  );
  return out;
}

if (import.meta.main) {
  const write = process.argv.includes("--write");
  const check = process.argv.includes("--check");
  if (!write && !check) {
    console.error("usage: bun packages/telemetry/tools/deploy-files.ts --write | --check");
    process.exit(2);
  }
  let stale = 0;
  for (const [path, content] of generated()) {
    const file = resolve(DEPLOY, path);
    let current = "";
    try {
      current = readFileSync(file, "utf8");
    } catch {}
    if (current === content) continue;
    stale += 1;
    if (write) {
      writeFileSync(file, content);
      console.log(`wrote ${path}`);
    } else console.error(`stale: ${path}`);
  }
  if (check && stale > 0) process.exit(1);
}
